  const dockAt = (x, y) => { const d = W.DATA.play.interactables.find(i => i.id === 'dock'); return d && Math.hypot(d.x - x, d.y - y) < d.r; };
  function nearest(x, y) { if (!D) return null; const sign = D.sign; if (Math.hypot(sign.x - x, sign.y - y) < 20) return { id: 'fish:sign', label: 'Read the signpost: far waters', x: sign.x, y: sign.y, r: 20, buildAct: () => openTravel() }; const w = nearestWater(x, y); if (!w) return null; const dock = dockAt(x, y); const c = WP.centre, dd = Math.hypot(c[0] - x, c[1] - y) || 1; const river = !dock && Math.hypot(w.x - D.pond.x, w.y - D.pond.y) > D.pond.r; const aim = river ? w : { x: w.x, y: w.y, d: 2, dx: (c[0] - x) / dd, dy: (c[1] - y) / dd }; return { id: dock ? 'dock' : 'fish:water', label: dock ? 'Fish from the platform' : river ? 'Fish the river' : 'Fish from the bank', x: w.x, y: w.y, r: 30, buildAct: () => openAt(river ? 'stream' : 'pond', dock ? 'platform' : 'shore', aim) }; }
  function openAt(habitat, spot, w) { if (Survival_sleeping()) return; S.habitat = habitat; S.spot = spot; S.water = w || null; S.state = 'panel'; S.row = 0; S.tool = W.Gather.Tools.active; if (W.Gather.Tools.owned.rod) W.Gather.Tools.select('rod'); const face = w; if (face) { const p = P(); if (Math.abs(face.dx) > Math.abs(face.dy)) { p.facing = 'side'; p.flip = face.dx < 0; } else { p.facing = face.dy < 0 ? 'up' : 'down'; p.flip = false; } } }
  const Survival_sleeping = () => W.Survival.Sleep.sleeping;
