  function canGo(h) { const H = HAB[h]; if (H.requires && H.requires.festival && !(window.Festival && window.Festival.active() === H.requires.festival)) return { ok: false, reason: H.requires.text }; if (H.requires && H.requires.found && !W.Gather.Journal.found[H.requires.found]) return { ok: false, reason: H.requires.text }; if (!W.Survival.Energy.canDo || W.Survival.Energy.current >= H.travel_energy) return { ok: true }; return { ok: false, reason: 'Too tired for that walk.' }; }
  function go(h, free) { const g = canGo(h); if (!g.ok) { say(g.reason); return g; } const H = HAB[h]; if (!free || H.travel_hours) { const r = W.Survival.Activities.performCustom('walk_' + h, { label: 'Walk', heavy: false, energy: H.travel_energy, minutes: Math.max(1, H.travel_hours * 60), anim: null }, 'trail'); if (!r.ok) { say(r.reason); return r; } } S.vista = h; if (!S.visited.includes(H.name)) S.visited.push(H.name); S.habitat = h; S.spot = 'vista'; S.state = 'panel'; S.row = 0; S.tool = S.tool || W.Gather.Tools.active; if (W.Gather.Tools.owned.rod) W.Gather.Tools.select('rod'); W.Monsters.clearAll(); say(H.name + '. ' + H.description, 5); return { ok: true }; }
  function goHome() { const H = HAB[S.vista]; if (H && H.travel_hours) W.Survival.Activities.performCustom('walk_home', { label: 'Walk', heavy: false, energy: 0, minutes: H.travel_hours * 60, anim: null }, 'trail'); S.vista = null; S.habitat = null; S.spot = null; S.state = 'idle'; S.fish = null; S.float = null; if (S.tool && W.Gather.Tools.owned[S.tool]) W.Gather.Tools.select(S.tool); S.tool = null; }
